/* Allocation is not changed when stack is cleared.     */
FT_LOCAL_DEF( void )
cff_blend_clear( CFF_SubFont  subFont )
{
  subFont->blend_top  = subFont->blend_stack;
  subFont->blend_used = 0;
}


